'use strict';
const $=id=>document.getElementById(id);
const desktopQuery=matchMedia('(min-width:900px)');
const desktop=()=>document.body.dataset.target==='web'&&desktopQuery.matches;
const seed=()=>[{id:'m-01',order:1,title:'회의 메모',body:'회의 메모',favorite:false},{id:'m-02',order:2,title:'이번 주 할 일',body:'이번 주 할 일을 정리합니다.',favorite:false},{id:'m-03',order:2,title:'아이디어',body:'다음에 살펴볼 아이디어입니다.',favorite:false}].map(m=>({...m,baseline:m.body,state:'EDITING',requested:''}));
let memos=seed(),selected=null,listY=0;
const current=()=>memos.find(m=>m.id===selected);
const locked=()=>{const m=current();return !!m&&(m.state==='SAVING'||m.body!==m.baseline);};
const messages={EMPTY:'본문을 입력하세요.',EDITING:'본문을 입력 중입니다.',SAVING:'가상 응답을 기다리는 중입니다. 중복 요청은 차단되며 실제 저장은 하지 않습니다.',SAVED:'메모가 저장됐어요 같은 화면에 요청한 본문을 표시합니다. 실제 저장·영속성은 보장하지 않습니다.',ERROR:'가상 저장에 실패했습니다. 요청한 본문은 그대로 유지되었습니다. 이것은 긴 오류 표시를 확인하기 위한 시험 문구입니다. 연결된 서비스는 없으며 실제 장애를 뜻하지 않습니다. 본문을 확인한 뒤 재시도하면 다시 가상 응답을 전달할 수 있습니다.'};
function button(text,action,id){const b=document.createElement('button');b.type='button';b.textContent=text;b.dataset.actionId=action;if(id)b.dataset.memoId=id;return b;}
function favorite(m,place){const b=button((m.favorite?'★ 즐겨찾기':'☆ 즐겨찾기'), 'ACT-FAV-TOGGLE',m.id);b.className='favorite';b.dataset.place=place;b.setAttribute('aria-pressed',String(m.favorite));b.setAttribute('aria-label',m.title+' 즐겨찾기 '+(m.favorite?'선택됨':'선택 안 됨'));b.onclick=()=>{m.favorite=!m.favorite;renderList();renderEditor();const root=place==='list'?$('rows'):$('editor');root.querySelector('[data-action-id="ACT-FAV-TOGGLE"][data-memo-id="'+m.id+'"]').focus({preventScroll:true});$('listStatus').textContent=m.title+' 즐겨찾기 '+(m.favorite?'선택':'해제');};return b;}
function renderList(){const rows=$('rows');rows.replaceChildren();const ordered=[...memos].sort((a,b)=>Number(b.favorite)-Number(a.favorite)||a.order-b.order||(a.id<b.id?-1:a.id>b.id?1:0));$('list').dataset.stateId=!memos.length?'LIST-EMPTY':memos.some(m=>m.favorite)?'LIST-MIXED':'LIST-DEFAULT';if(!ordered.length){const p=document.createElement('p');p.textContent='메모가 없습니다.';rows.append(p);}ordered.forEach(m=>{const row=document.createElement('div');row.className='memo-row';row.dataset.memoId=m.id;const open=button(m.title,'ACT-MEMO-OPEN',m.id);open.className='memo-open';open.disabled=locked();if(selected===m.id)open.setAttribute('aria-current','true');open.onclick=()=>{if(locked())return;listY=desktop()?$('list').scrollTop:window.scrollY;selected=m.id;render();$('editorHeading').focus();if(!desktop())window.scrollTo(0,0);};row.append(open,favorite(m,'list'));rows.append(row);});}
function returnList(){if(locked())return;const previous=selected;if(desktop()){const b=$('rows').querySelector('[data-action-id="ACT-MEMO-OPEN"][data-memo-id="'+previous+'"]');if(b)b.focus();return;}selected=null;render();window.scrollTo(0,listY);const b=$('rows').querySelector('[data-action-id="ACT-MEMO-OPEN"][data-memo-id="'+previous+'"]');if(b)b.focus({preventScroll:true});}
function renderEditor(){const root=$('editor'),m=current();root.replaceChildren();root.hidden=!m&&!desktop();if(!m){root.dataset.stateId='NO-SELECTION';if(desktop()){const p=document.createElement('p');p.textContent=memos.length?'一覧からメモを選択してください。'.replace('一覧からメモを選択してください。','목록에서 메모를 선택하세요.'):'메모가 없습니다.';root.append(p);}controls();return;}root.dataset.memoId=m.id;root.dataset.stateId=m.state;root.dataset.favoriteState=m.favorite?'FAV-ON':'FAV-OFF';const back=button(desktop()?'목록으로 포커스 이동':'목록으로','ACT-LIST-RETURN');back.className='back';back.disabled=locked();back.onclick=returnList;const header=document.createElement('div');header.className='editor-head';const h=document.createElement('h2');h.id='editorHeading';h.tabIndex=-1;h.textContent=m.title;header.append(h,favorite(m,'editor'));root.append(back,header);const snapshotMode=m.state==='SAVING'||m.state==='SAVED';if(snapshotMode){const label=document.createElement('h3');label.textContent='요청한 본문';const pre=document.createElement('pre');pre.className='snapshot';pre.tabIndex=0;pre.setAttribute('aria-label','요청한 본문');pre.dataset.componentId='COMP-004';pre.textContent=m.requested;root.append(label,pre);}else{const label=document.createElement('label');label.htmlFor='body';label.textContent='본문';const input=document.createElement('textarea');input.id='body';input.value=m.body;input.dataset.actionId='ACT-001';input.dataset.componentId='COMP-001';input.setAttribute('aria-describedby','scope saveStatus');input.oninput=()=>{m.body=input.value;m.state=m.body.length?'EDITING':'EMPTY';root.dataset.stateId=m.state;updateStatus(m);$('save').hidden=m.state!=='EDITING'||!/\S/u.test(m.body);$('backMarker').disabled=locked();renderList();};root.append(label,input);}back.id='backMarker';const scope=document.createElement('p');scope.id='scope';scope.className='scope';scope.textContent='실제 저장·영속성은 보장하지 않습니다. 빈 값·공백 저장, 길이 제한, 미저장 이탈·처리 중 편집 정책은 미정입니다. 본문 변경 또는 응답 대기 중에는 이번 샘플의 화면 이동을 제공하지 않습니다.';const status=document.createElement('p');status.id='saveStatus';status.tabIndex=-1;status.dataset.componentId='COMP-003';status.setAttribute('role','status');status.setAttribute('aria-live','polite');status.setAttribute('aria-atomic','true');root.append(scope,status);updateStatus(m);const save=button('가상 저장','ACT-002');save.id='save';save.hidden=m.state!=='EDITING'||!/\S/u.test(m.body);save.onclick=request;const busy=button('가상 응답 대기 중','ACT-003');busy.disabled=true;busy.hidden=m.state!=='SAVING';const retry=button('재시도','ACT-006');retry.hidden=m.state!=='ERROR';retry.disabled=!/\S/u.test(m.body);retry.onclick=request;root.append(save,busy,retry);controls();}
function updateStatus(m){const status=$('saveStatus');status.dataset.stateId=m.state;status.className=m.state==='ERROR'?'error':'muted';status.textContent=messages[m.state];}
function controls(){const m=current();$('success').disabled=!m||m.state!=='SAVING';$('failure').disabled=!m||m.state!=='SAVING';$('statePicker').disabled=!m;$('longBody').disabled=!m;if(m)$('statePicker').value=m.state;}
function render(){const y=$('list').scrollTop;renderList();$('list').hidden=!!selected&&!desktop();renderEditor();if(desktop())$('list').scrollTop=y;}
function request(){const m=current();if(!m||!['EDITING','ERROR'].includes(m.state)||!/\S/u.test(m.body))return;m.requested=m.body;m.state='SAVING';render();$('saveStatus').focus();}
$('success').onclick=()=>{const m=current();if(!m||m.state!=='SAVING')return;m.state='SAVED';m.baseline=m.body;render();$('saveStatus').focus();};
$('failure').onclick=()=>{const m=current();if(!m||m.state!=='SAVING')return;m.body=m.requested;m.state='ERROR';render();$('saveStatus').focus();};
$('reset').onclick=()=>{memos=seed();selected=null;render();$('listHeading').focus();};
$('emptyList').onclick=()=>{memos=[];selected=null;render();$('listHeading').focus();};
$('statePicker').onchange=()=>{const m=current();if(!m)return;m.state=$('statePicker').value;m.body=m.state==='EMPTY'?'':m.body||'회의 메모';m.baseline=m.body;m.requested=m.body;render();$('saveStatus').focus();};
$('longBody').onclick=()=>{const m=current();if(!m)return;m.body=('긴 본문 불변 확인용 메모입니다. '+'연속문자'.repeat(30)+'\n').repeat(12);m.baseline=m.body;m.state='EDITING';render();$('body').focus();};
desktopQuery.addEventListener('change',()=>{render();if(current())$('editorHeading').focus();else $('listHeading').focus();});
render();
